CREATE TYPE "ContentStatus" AS ENUM ('DRAFT', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "EnquiryStatus" AS ENUM ('NEW', 'ASSIGNED', 'CONTACTED', 'QUALIFIED', 'CONVERTED', 'CLOSED');

CREATE TABLE "pages" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "summary" TEXT NOT NULL, "body" TEXT NOT NULL, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "seoTitle" TEXT, "seoDescription" TEXT, "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "pages_pkey" PRIMARY KEY ("id"));
CREATE TABLE "services" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "pillar" TEXT NOT NULL, "summary" TEXT NOT NULL, "description" TEXT NOT NULL, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "sortOrder" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "services_pkey" PRIMARY KEY ("id"));
CREATE TABLE "work_items" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "shortDescription" TEXT NOT NULL, "fullDescription" TEXT NOT NULL, "year" INTEGER, "category" TEXT NOT NULL, "clientOrPartner" TEXT, "location" TEXT, "challenge" TEXT, "approach" TEXT, "outcomes" TEXT, "heroImage" TEXT, "featured" BOOLEAN NOT NULL DEFAULT false, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "work_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "articles" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "excerpt" TEXT NOT NULL, "body" TEXT NOT NULL, "authorName" TEXT NOT NULL, "topic" TEXT NOT NULL, "featuredImage" TEXT, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "publishedAt" TIMESTAMP(3), "seoTitle" TEXT, "seoDescription" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "articles_pkey" PRIMARY KEY ("id"));
CREATE TABLE "celive_episodes" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "episodeNumber" INTEGER, "guestName" TEXT, "guestOrganisation" TEXT, "summary" TEXT NOT NULL, "videoUrl" TEXT, "transcript" TEXT, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "publishedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "celive_episodes_pkey" PRIMARY KEY ("id"));
CREATE TABLE "team_members" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "roleTitle" TEXT NOT NULL, "biography" TEXT NOT NULL, "imageUrl" TEXT, "sortOrder" INTEGER NOT NULL DEFAULT 0, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "team_members_pkey" PRIMARY KEY ("id"));
CREATE TABLE "media_assets" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "altText" TEXT, "isPublic" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "media_assets_pkey" PRIMARY KEY ("id"));
CREATE TABLE "site_settings" ("id" TEXT NOT NULL, "key" TEXT NOT NULL, "value" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "site_settings_pkey" PRIMARY KEY ("id"));
CREATE TABLE "contacts" ("id" TEXT NOT NULL, "firstName" TEXT NOT NULL, "lastName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "organisation" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "contacts_pkey" PRIMARY KEY ("id"));
CREATE TABLE "enquiries" ("id" TEXT NOT NULL, "contactId" TEXT NOT NULL, "enquiryType" TEXT NOT NULL, "message" TEXT NOT NULL, "preferredContactMethod" TEXT, "budgetRange" TEXT, "timeline" TEXT, "projectLocation" TEXT, "consent" BOOLEAN NOT NULL, "status" "EnquiryStatus" NOT NULL DEFAULT 'NEW', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "enquiries_pkey" PRIMARY KEY ("id"));
CREATE TABLE "crm_activities" ("id" TEXT NOT NULL, "contactId" TEXT NOT NULL, "enquiryId" TEXT, "type" TEXT NOT NULL, "summary" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "crm_activities_pkey" PRIMARY KEY ("id"));

CREATE UNIQUE INDEX "pages_slug_key" ON "pages"("slug"); CREATE INDEX "pages_status_publishedAt_idx" ON "pages"("status", "publishedAt");
CREATE UNIQUE INDEX "services_slug_key" ON "services"("slug"); CREATE INDEX "services_status_pillar_sortOrder_idx" ON "services"("status", "pillar", "sortOrder");
CREATE UNIQUE INDEX "work_items_slug_key" ON "work_items"("slug"); CREATE INDEX "work_items_status_featured_publishedAt_idx" ON "work_items"("status", "featured", "publishedAt");
CREATE UNIQUE INDEX "articles_slug_key" ON "articles"("slug"); CREATE INDEX "articles_status_publishedAt_idx" ON "articles"("status", "publishedAt");
CREATE UNIQUE INDEX "celive_episodes_slug_key" ON "celive_episodes"("slug"); CREATE INDEX "celive_episodes_status_publishedAt_idx" ON "celive_episodes"("status", "publishedAt");
CREATE UNIQUE INDEX "team_members_slug_key" ON "team_members"("slug"); CREATE INDEX "team_members_status_sortOrder_idx" ON "team_members"("status", "sortOrder");
CREATE UNIQUE INDEX "site_settings_key_key" ON "site_settings"("key");
CREATE UNIQUE INDEX "contacts_email_key" ON "contacts"("email");
CREATE INDEX "enquiries_status_createdAt_idx" ON "enquiries"("status", "createdAt"); CREATE INDEX "enquiries_contactId_idx" ON "enquiries"("contactId");
CREATE INDEX "crm_activities_contactId_createdAt_idx" ON "crm_activities"("contactId", "createdAt"); CREATE INDEX "crm_activities_enquiryId_idx" ON "crm_activities"("enquiryId");

ALTER TABLE "enquiries" ADD CONSTRAINT "enquiries_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "contacts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "crm_activities" ADD CONSTRAINT "crm_activities_contactId_fkey" FOREIGN KEY ("contactId") REFERENCES "contacts"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "crm_activities" ADD CONSTRAINT "crm_activities_enquiryId_fkey" FOREIGN KEY ("enquiryId") REFERENCES "enquiries"("id") ON DELETE SET NULL ON UPDATE CASCADE;
